{
  "options": [
    {
      "id": "A",
      "name": "Dynamic PK Sub-visits and Dedicated Procedure Forms",
      "summary": "Create dynamic scheduled events for the seven PK subgroup visits triggered by RAND.PKSUB, add dedicated ADA and Patient Diary forms, and expand PKTPT and edit checks for the updated eligibility and infusion windows.",
      "pros": [
        "Dynamic events V2.1, V2.2, V2.3, V7.1, V7.2, V7.3, and V8.1 appear only for subjects enrolled in the PK substudy (RAND.PKSUB = 'Yes'), keeping non-PK casebooks clean.",
        "Explicitly mirrors the protocol visit schedule and enforces exact target days (Days 2, 6, 10, 72, 76, 80, 91) and SDV100 tracking per sub-visit.",
        "Dedicated ADA and DIARY forms along with new edit checks for the Day -35 to -6 endoscopy window and 2-hour infusion duration maximize data quality."
      ],
      "cons": [
        "Adds seven new events, two new forms, and multiple edit checks and dynamic rules, increasing build and UAT effort.",
        "Requires cross-event rules to activate the PK sub-visits from the Randomisation form."
      ],
      "tradeoff": "This option gives sites a clean schedule where PK subgroup visits appear automatically only when needed. It costs extra build and testing effort for the seven dynamic visits and new rules.",
      "recommended": true
    },
    {
      "id": "B",
      "name": "Consolidate PK Sub-samples onto Parent Visits",
      "summary": "Keep the existing event schedule unchanged by collecting the 48 h, 144 h, and 240 h PK samples on the parent visits (V2, V7, V8) via the expanded PKTPT codelist, while adding minimal ADA and Diary forms.",
      "pros": [
        "Avoids creating seven new events and dynamic event triggers, keeping the event matrix and SDV plan simple.",
        "Still captures all required PK timepoints (48 h, 144 h, 240 h), ADA at V3, and Diary administration at V2."
      ],
      "cons": [
        "Sites must enter multi-day follow-up samples under the parent visit folder (V2, V7, V8), which does not match the protocol visit numbering (V2.1–V8.1).",
        "Harder to track overdue or missed PK sub-visits in EDC visit projection and monitoring reports."
      ],
      "tradeoff": "This option avoids adding seven new visits to the event matrix by folding all PK timepoints into the existing parent visits. It costs visit-level tracking and deviates from the protocol's explicit sub-visit numbering.",
      "recommended": false
    },
    {
      "id": "C",
      "name": "Static Always-On PK Sub-visits with Granular Eligibility Items",
      "summary": "Add V2.1 through V8.1 as static scheduled visits for all subjects (using PKPERF='No' when not applicable) and expand IE and TB forms with explicit criterion-level items for the new endoscopy, diary literacy, and latent TB criteria.",
      "pros": [
        "No dynamic event rules required, eliminating rule dependencies on the RAND form.",
        "Granular items on IE and TB explicitly verify the Day -35 to -6 endoscopy window, Criterion 8 diary literacy, and QuantiFERON/T-spot/chest X-ray latent TB rules."
      ],
      "cons": [
        "Clutters the casebook for non-PK subjects with seven unused visits that must be marked not performed or left blank.",
        "Over-engineers the existing summary-level IE and TB forms, which currently use single summary items (IEMET, TBRES)."
      ],
      "tradeoff": "This option removes dynamic rule complexity and enforces every new eligibility detail with dedicated fields. It burdens sites with seven extra visits for non-PK patients and breaks the simple summary style of the existing forms.",
      "recommended": false
    }
  ]
}
